// Üretilen dosya: tool/ozgun/uret.py. Matematik · Geometri: üçgenler, dörtgenler, çember, katı cisimler (orta).
const ozMathematics3Orta = <(String, String, List<String>, String)>[
  ('Bir açının tümleri ile bütünlerinin ölçüleri toplamı 210° ise bu açı kaç derecedir?', '30°', ['40°', '45°', '37,5°'], '(90 − x) + (180 − x) = 210 olur, buradan 270 − 2x = 210 ve x = 30° bulunur.'),
  ('Bütünleri, tümlerinin 4 katı olan açı kaç derecedir?', '60°', ['45°', '50°', '67,5°'], '180 − x = 4(90 − x) eşitliğinden 180 − x = 360 − 4x, yani 3x = 180 ve x = 60° olur.'),
  ('İki paralel doğru ve bir kesen verildiğinde, kesenin aynı tarafında paralellerin arasında kalan iki açıdan biri 3x + 10°, diğeri 2x + 20° ise x kaçtır?', '30', ['26', '34', '37,5'], 'Karşı durumlu (aynı taraftaki iç) açılar bütünlerdir: 5x + 30 = 180, x = 30 olur.'),
  ('Bir duvar saatinde yelkovan 6\'nın, akrep ise 3 ile 4\'ün tam ortasının üzerindeyken iki ibre arasındaki küçük açı kaç derecedir?', '75°', ['60°', '90°', '105°'], 'Yelkovan 6\'dadır (180°), akrep 3 ile 4\'ün tam ortasındadır (105°). Aradaki fark 180 − 105 = 75°\'dir.'),
  ('Bir noktadan çıkan dört ışın, tam açıyı ölçüleri 2, 3, 4 ve 6 ile orantılı dört açıya bölüyor. En büyük açı kaç derecedir?', '144°', ['120°', '135°', '157,5°'], 'Toplam pay 15\'tir. 360° / 15 = 24°, en büyük açı 6 · 24 = 144° olur.'),
  ('Komşu bütünler iki açının açıortayları arasındaki açı kaç derecedir?', '90°', ['45°', '60°', '180°'], 'Açılar x ve 180 − x ise yarılarının toplamı x/2 + (180 − x)/2 = 90° olur.'),
  ('Ölçüsü 0°\'den büyük 90°\'den küçük iki açının bütünlerinin toplamı 250° ise bu iki açının toplamı kaç derecedir?', '110°', ['70°', '90°', '130°'], '(180 − a) + (180 − b) = 250 olduğundan a + b = 360 − 250 = 110°\'dir.'),
  ('Paralel iki doğruyu kesen bir doğrunun oluşturduğu sekiz açıdan biri 72° ise bu sekiz açı arasında 108° ölçülü kaç açı vardır?', '4', ['2', '3', '6'], 'Sekiz açıdan dördü 72°, dördü 108°\'dir; çünkü her kesişim noktasında iki çift ters açı oluşur ve paralellik açıları taşır.'),
  ('Ölçüsü 37° 45′ olan bir açının tümleri kaçtır?', '52° 15′', ['52° 55′', '53° 15′', '52° 45′ 30″'], '90° = 89° 60′ olarak yazılır. 89° 60′ − 37° 45′ = 52° 15′ bulunur.'),
  ('Bir açının bütünleri, tümlerinden her zaman kaç derece fazladır?', '90°', ['45°', '180°', 'Açıya göre değişir.'], '(180 − x) − (90 − x) = 90 olduğundan fark açıdan bağımsız olarak 90°\'dir.'),
  ('ABC üçgeninde A açısı 70°\'dir. B ve C açılarının iç açıortaylarının kesiştiği noktada oluşan BIC açısı kaç derecedir?', '125°', ['110°', '115°', '117,5°'], 'İç açıortaylar için BIC = 90° + A/2 bağıntısı geçerlidir: 90 + 35 = 125°.'),
  ('Bir ikizkenar üçgenin bir açısı 100° ise diğer açılardan biri kaç derece olmak zorundadır?', '40°', ['80°', '50°', '100°'], '100° bir taban açısı olamaz, çünkü iki taban açısı 200° eder. Demek ki tepe açısıdır ve taban açıları (180 − 100)/2 = 40° olur.'),
  ('Kenar uzunlukları 5 cm ve 9 cm olan bir üçgenin üçüncü kenarı tam sayı olmak üzere kaç farklı değer alabilir?', '9', ['8', '10', '13'], 'Üçgen eşitsizliğine göre 9 − 5 < x < 9 + 5, yani 4 < x < 14. Tam sayı değerleri 5\'ten 13\'e kadar 9 tanedir.'),
  ('Kenarları 7, 8 ve x birim olan bir üçgende en büyük açı x kenarının karşısındadır. x tam sayı ise en çok kaç olabilir?', '14', ['13', '15', '16'], 'Üçgen eşitsizliğinden x < 15 olur. x\'in karşısındaki açı en büyük olduğundan x > 8 olmalıdır. En büyük tam değer 14\'tür.'),
  ('ABC üçgeninde A = 75°, B = 60° ise kenarlar arasındaki doğru sıralama hangisidir? (a, b, c sırasıyla A, B, C\'nin karşısındaki kenarlardır.)', 'a > b > c', ['a > c > b', 'b > a > c', 'c > b > a'], 'C = 180 − 75 − 60 = 45°\'dir. Açılar A > B > C sıralandığından kenarlar da a > b > c olur.'),
  ('Kenar uzunlukları 6, 8 ve 11 olan bir üçgen açılarına göre nasıl bir üçgendir?', 'Geniş açılı üçgen', ['Dar açılı üçgen', 'Dik üçgen', 'Eşkenar üçgen'], '11² = 121, 6² + 8² = 100 eder. En uzun kenarın karesi diğer ikisinin kareleri toplamından büyük olduğundan en büyük açı geniştir.'),
  ('Kenarları 5, 6 ve 7 olan üçgen açılarına göre hangi türdendir?', 'Dar açılı üçgen', ['Geniş açılı üçgen', 'Dik üçgen', 'Eşkenar üçgen'], '7² = 49 < 5² + 6² = 61 olduğundan en büyük açı bile dardır, üçgen dar açılıdır.'),
  ('Bir üçgenin iki iç açısının toplamı üçüncü açıya eşitse bu üçgen için ne söylenebilir?', 'Dik üçgendir.', ['Eşkenar üçgendir.', 'Geniş açılı üçgendir.', 'Dar açılı ikizkenar üçgendir.'], 'x + y = z ve x + y + z = 180 olduğundan 2z = 180, z = 90° bulunur. Üçgen dik üçgendir.'),
  ('Bir ABC üçgeninde B açısı C açısından büyükse aşağıdakilerden hangisi kesinlikle doğrudur?', 'AC kenarı AB kenarından uzundur.', ['AB kenarı AC kenarından uzundur.', 'BC en kısa kenardır.', 'A açısı en büyük açıdır.'], 'B açısının karşısındaki kenar AC, C açısının karşısındaki kenar AB\'dir. B > C olduğundan AC > AB olur.'),
  ('Karşılıklı üç açısı eşit olan iki üçgen için aşağıdakilerden hangisi kesinlikle doğrudur?', 'Benzerdirler ama eş olmayabilirler.', ['Her zaman eştirler.', 'Alanları her zaman birbirine eşittir.', 'Çevreleri her zaman eşittir.'], 'Açıların eşliği yalnız biçimi belirler, büyüklüğü belirlemez. Bu nedenle AAA benzerlik kuralıdır, eşlik kuralı değildir.'),
  ('ABC üçgeninde DE doğru parçası BC\'ye paraleldir ve D noktası AB, E noktası AC üzerindedir. AD = 4, DB = 6 ve DE = 6 ise BC kaçtır?', '15', ['9', '10', '12,5'], 'ADE ile ABC benzerdir: AD/AB = DE/BC, yani 4/10 = 6/BC ve BC = 15 olur.'),
  ('Boyu 1,8 m olan bir kişinin gölgesi 1,2 m uzunluğundadır. Aynı anda gölgesi 8 m olan bir ağacın boyu kaç metredir?', '12 m', ['10 m', '10,8 m', '13,5 m'], 'Güneş ışınları aynı açıyla geldiği için oluşan üçgenler benzerdir: 1,8/1,2 = h/8, h = 12 m bulunur.'),
  ('Benzer iki üçgenin çevreleri 18 cm ve 30 cm\'dir. Küçük üçgenin bir yüksekliği 6 cm ise büyük üçgende buna karşılık gelen yükseklik kaç cm\'dir?', '10 cm', ['8 cm', '12 cm', '16,6 cm'], 'Benzer üçgenlerde çevreler oranı ve karşılıklı yükseklikler oranı benzerlik oranına eşittir: 30/18 = 5/3. 6 · 5/3 = 10 cm.'),
  ('ABC üçgeninde AD, A açısının iç açıortayıdır ve D noktası BC üzerindedir. AB = 6, AC = 9 ve BC = 10 ise BD kaçtır?', '4', ['3', '5', '4,5'], 'İç açıortay teoremi: BD/DC = AB/AC = 6/9 = 2/3. BD = 10 · 2/5 = 4 olur.'),
  ('İç açıortay teoremi bir üçgende hangi oranın eşit olduğunu söyler?', 'Açıortayın ayırdığı parçaların oranı ile komşu kenarların oranının', ['Açıortay uzunluğu ile karşı kenarın oranının', 'İki yüksekliğin oranı ile karşılarındaki iki kenarın oranının', 'Kenarortay ile açıortayın oranının'], 'Açıortay karşı kenarı, açıyı oluşturan iki kenarla aynı oranda böler: BD/DC = AB/AC.'),
  ('Bir üçgenin üç kenarortayı üçgeni kaç tane alanca eş küçük üçgene ayırır?', '6', ['3', '4', '9'], 'Üç kenarortay ağırlık merkezinde kesişir ve üçgeni alanları birbirine eşit altı küçük üçgene böler.'),
  ('Alanı 54 cm² olan ABC üçgeninin ağırlık merkezi G\'dir. GBC üçgeninin alanı kaç cm²\'dir?', '18 cm²', ['9 cm²', '27 cm²', '13,5 cm²'], 'Ağırlık merkezinin BC\'ye uzaklığı A\'nın BC\'ye uzaklığının üçte biridir. Bu yüzden GBC alanı 54/3 = 18 cm² olur.'),
  ('Bir ABC üçgeninin köşeleri A(1, 2), B(5, 4) ve C(3, 9) ise ağırlık merkezinin koordinatları nedir?', '(3, 5)', ['(3, 4)', '(4, 5)', '(9, 15)'], 'Ağırlık merkezi köşe koordinatlarının ortalamasıdır: ((1+5+3)/3, (2+4+9)/3) = (3, 5).'),
  ('İki üçgenden birinin kenarları 3, 4, 6, diğerinin kenarları 4,5, 6, 9 birimdir. Bu üçgenler için hangisi doğrudur?', 'Benzerdirler ve benzerlik oranı 3/2\'dir.', ['Eştirler.', 'Benzer değildirler.', 'Benzerdirler ve benzerlik oranı 2\'dir.'], 'Karşılıklı kenar oranları 4,5/3 = 6/4 = 9/6 = 3/2\'dir. KKK benzerlik kuralı sağlanır.'),
  ('Geniş açılı bir üçgenin diklik merkezi nerede bulunur?', 'Üçgenin dışında', ['Üçgenin içinde', 'En uzun kenarın orta noktasında', 'Geniş açılı köşenin tam üzerinde'], 'Geniş açılı üçgende geniş açıya komşu kenarlara ait yükseklikler dışarıda kalır. Bu yüzden yüksekliklerin uzantıları üçgenin dışında kesişir.'),
  ('Bir dik üçgenin diklik merkezi hangi noktadır?', 'Dik açının bulunduğu köşe', ['Hipotenüsün orta noktası', 'Ağırlık merkezi ile aynı nokta', 'Hipotenüse ait yüksekliğin orta noktası'], 'Dik üçgende iki dik kenar birbirinin yüksekliğidir ve dik köşede kesişir. Üçüncü yükseklik de bu köşeden geçer.'),
  ('Bir üçgenin kenar orta dikmelerinin kesiştiği nokta hangi özelliğe sahiptir?', 'Üç köşeye eşit uzaklıktadır.', ['Üç kenara eşit uzaklıktadır.', 'Kenarortayları 2 : 1 oranında böler.', 'Her zaman üçgenin içinde kalır.'], 'Kenar orta dikme üzerindeki her nokta kenarın iki ucuna eşit uzaklıktadır. Üç dikmenin kesişimi bu yüzden üç köşeye eşit uzaklıktadır ve çevrel çemberin merkezidir.'),
  ('Dik kenarları 5 cm ve 12 cm olan bir dik üçgenin çevrel çemberinin yarıçapı kaç cm\'dir?', '6,5 cm', ['5 cm', '6 cm', '8,5 cm'], 'Hipotenüs √(25 + 144) = 13 cm\'dir. Dik üçgende çevrel çemberin merkezi hipotenüsün orta noktası olduğundan R = 13/2 = 6,5 cm olur.'),
  ('Kenarları 20, 21 ve 29 birim olan bir üçgenin alanı kaç birimkaredir?', '210', ['290', '305', '420'], '20² + 21² = 400 + 441 = 841 = 29² olduğundan üçgen diktir. Alan 20 · 21 / 2 = 210 birimkare olur.'),
  ('Dik kenarları 6 cm ve 8 cm olan bir dik üçgende hipotenüse ait yükseklik kaç cm\'dir?', '4,8 cm', ['4 cm', '5 cm', '5,25 cm'], 'Hipotenüs 10 cm\'dir. Alanı iki biçimde yazarsak 6 · 8 = 10 · h, h = 4,8 cm bulunur.'),
  ('Bir dik üçgende hipotenüse ait yükseklik, hipotenüsü 4 cm ve 9 cm uzunluğunda iki parçaya ayırıyor. Bu yükseklik kaç cm\'dir?', '6 cm', ['5 cm', '6,5 cm', '13 cm'], 'Öklid bağıntısına göre h² = p · k = 4 · 9 = 36, h = 6 cm olur.'),
  ('Öklid\'in dik üçgen bağıntılarından h² = p · k eşitliğinde p ve k neyi gösterir?', 'Hipotenüse ait yüksekliğin hipotenüs üzerinde ayırdığı iki parçayı', ['İki dik kenarın uzunluklarını', 'Hipotenüs ile bir dik kenarın uzunluğunu', 'Çevrel ve iç teğet çember yarıçaplarını'], 'h hipotenüse ait yüksekliktir. Ayağı hipotenüsü p ve k parçalarına ayırır ve yüksekliğin karesi bu iki parçanın çarpımına eşittir.'),
  ('Kenarları 10, 10 ve 12 cm olan ikizkenar üçgende tabana ait yükseklik kaç cm\'dir?', '8 cm', ['6 cm', '√136 cm', '9 cm'], 'Tabana ait yükseklik tabanı ikiye böler. 6 cm ve 10 cm ile dik üçgen oluşur: √(100 − 36) = 8 cm.'),
  ('Hipotenüsü 17 cm, bir dik kenarı 8 cm olan dik üçgenin alanı kaç cm²\'dir?', '60 cm²', ['68 cm²', '120 cm²', '136 cm²'], 'Diğer dik kenar √(289 − 64) = 15 cm\'dir. Alan 8 · 15 / 2 = 60 cm² olur.'),
  ('Bir dik üçgenin dik kenarları 1 ve √3 birimse en küçük açısı kaç derecedir?', '30°', ['15°', '45°', '60°'], 'Hipotenüs √(1 + 3) = 2 olur. Kısa kenar hipotenüsün yarısı olduğundan karşısındaki açı 30°\'dir.'),
  ('Bir dar açı için sin x = 5/13 ise tan x kaçtır?', '5/12', ['12/13', '12/5', '13/12'], 'Karşı kenar 5, hipotenüs 13 alınırsa komşu kenar √(169 − 25) = 12 olur. tan x = 5/12\'dir.'),
  ('Dik üçgende bir dar açının tanjantı 3/4 ve hipotenüs 20 cm ise üçgenin çevresi kaç cm\'dir?', '48 cm', ['36 cm', '44 cm', '56 cm'], 'Dik kenarlar 3k ve 4k, hipotenüs 5k olur. 5k = 20 ise k = 4, kenarlar 12 ve 16\'dır. Çevre 12 + 16 + 20 = 48 cm.'),
  ('İki kenarı 6 cm ve 8 cm, bu kenarlar arasındaki açısı 30° olan üçgenin alanı kaç cm²\'dir?', '12 cm²', ['24 cm²', '12√3 cm²', '14 cm²'], 'Alan = (1/2) · a · b · sin C = (1/2) · 6 · 8 · (1/2) = 12 cm².'),
  ('Heron formülü kullanıldığında, kenar uzunlukları 13, 14 ve 15 olan bir üçgensel bölge kaç birimkare yer kaplar?', '84', ['72', '91', '105'], 'Heron formülünde u = 21\'dir. Alan = √(21 · 8 · 7 · 6) = √7056 = 84 bulunur.'),
  ('Kenarları 10 cm ve 6 cm, aralarındaki açı 150° olan bir üçgenin alanı kaç cm²\'dir?', '15 cm²', ['30 cm²', '15√3 cm²', '7,5 cm²'], 'sin 150° = sin 30° = 1/2\'dir. Alan = (1/2) · 10 · 6 · (1/2) = 15 cm².'),
  ('ABC üçgeninde D noktası BC üzerindedir ve BD : DC = 2 : 3\'tür. ABC\'nin alanı 40 cm² ise ABD üçgeninin alanı kaç cm²\'dir?', '16 cm²', ['8 cm²', '20 cm²', '24 cm²'], 'ABD ve ADC üçgenleri A\'dan çıkan aynı yüksekliği paylaşır. Alanları tabanlarıyla orantılıdır: 40 · 2/5 = 16 cm².'),
  ('Bir üçgenin kenarlarının orta noktaları birleştirilerek oluşturulan üçgenin alanı, ilk üçgenin alanının kaçta kaçıdır?', '1/4', ['1/2', '1/3', '1/8'], 'Orta tabanlar ilk üçgene 1/2 oranında benzer bir üçgen oluşturur. Alan oranı (1/2)² = 1/4 olur.'),
  ('Bir ABC üçgeninde A = 30° ve a = 7 cm ise çevrel çemberin yarıçapı kaç cm\'dir?', '7 cm', ['3,5 cm', '14 cm', '7√3 cm'], 'Sinüs teoremine göre a / sin A = 2R\'dir: 7 / (1/2) = 14 = 2R, R = 7 cm.'),
  ('ABC üçgeninde b = 5, c = 8 ve A = 60° ise a kenarı kaç birimdir?', '7', ['6', '√89', '9'], 'Kosinüs teoremi: a² = 25 + 64 − 2 · 5 · 8 · (1/2) = 49 olduğundan a = 7\'dir.'),
  ('Kosinüs teoremi, açılardan biri 90° olduğunda hangi teoreme dönüşür?', 'Pisagor teoremine', ['Thales teoremine', 'Sinüs teoremine', 'Menelaus teoremine'], 'a² = b² + c² − 2bc · cos A formülünde A = 90° için cos A = 0 olur ve a² = b² + c² elde edilir.'),
  ('Bir marangoz, dik kenarları 6 dm ve 8 dm olan üçgen bir tahtaya üç kenara da değen en büyük daireyi çizmek istiyor. Bu dairenin yarıçapı kaç dm olur?', '2', ['2,4', '3', '4'], 'Dik üçgende r = (a + b − c)/2 formülüyle 6 + 8 − 10 = 4 ve r = 2 bulunur.'),
  ('On kenarlı bir çokgenin toplam köşegen sayısı kaçtır?', '35', ['30', '40', '45'], 'Köşegen sayısı n(n − 3)/2 ile hesaplanır: 10 · 7 / 2 = 35.'),
  ('Toplam 20 köşegeni olan dışbükey çokgen kaç kenarlıdır?', '8', ['7', '9', '10'], 'n(n − 3)/2 = 20 ise n(n − 3) = 40 olur. n = 8 için 8 · 5 = 40 sağlanır.'),
  ('İç açılarının toplamı dış açılarının toplamının 4 katı olan dışbükey çokgen kaç kenarlıdır?', '10', ['8', '9', '12'], 'Dış açılar toplamı 360°\'dir. (n − 2) · 180 = 1440 ise n − 2 = 8, n = 10 bulunur.'),
  ('Dışbükey bir n-genin bir köşesinden çizilen tüm köşegenler, çokgeni kaç üçgensel bölgeye ayırır?', 'n − 2', ['n − 3', 'n − 1', 'n'], 'Bir köşeden n − 3 köşegen çizilir ve bunlar çokgeni n − 2 üçgene böler. İç açılar toplamı formülü de buradan gelir.'),
  ('Her bir iç açısı 140° olan düzgün çokgen kaç kenarlıdır?', '9', ['7', '8', '10'], 'Bir dış açı 180 − 140 = 40°\'dir. Dış açılar toplamı 360° olduğundan kenar sayısı 360 / 40 = 9 olur.'),
  ('Bir kenarı 4 cm olan düzgün altıgenin alanı kaç cm²\'dir?', '24√3 cm²', ['16√3 cm²', '48√3 cm²', '12√3 cm²'], 'Düzgün altıgen, kenarı 4 cm olan altı eşkenar üçgene ayrılır: 6 · (16√3/4) = 24√3 cm².'),
  ('Bir kenarı 5 cm olan düzgün altıgenin en uzun köşegeni kaç cm\'dir?', '10 cm', ['5√3 cm', '5√2 cm', '12,5 cm'], 'En uzun köşegen merkezden geçer ve iki eşkenar üçgenin kenarlarından oluşur: 2 · 5 = 10 cm.'),
  ('Aşağıdaki düzgün çokgenlerden hangisinin eş kopyaları, tek başına, boşluk ve örtüşme olmadan düzlemi kaplayamaz?', 'Düzgün beşgen', ['Eşkenar üçgen', 'Kare', 'Düzgün altıgen'], 'Bir köşede buluşan açıların toplamı 360° olmalıdır. 360 / 108 tam sayı olmadığı için düzgün beşgen düzlemi kaplayamaz. 60°, 90° ve 120° ise 360\'ı tam böler.'),
  ('Köşegenleri birbirine dik olan bir dörtgenin köşegenleri 10 cm ve 7 cm ise alanı kaç cm²\'dir?', '35 cm²', ['17,5 cm²', '70 cm²', '34 cm²'], 'Köşegenleri dik kesişen dörtgenin alanı köşegenler çarpımının yarısıdır: 10 · 7 / 2 = 35 cm².'),
  ('Herhangi bir dörtgenin kenarlarının orta noktaları birleştirildiğinde her zaman hangi şekil elde edilir?', 'Paralelkenar', ['Kare', 'Yamuk', 'Deltoit'], 'Varignon teoremine göre orta noktaları birleştiren dörtgenin kenarları köşegenlere paralel ve onların yarısı uzunluğundadır. Karşılıklı kenarlar paralel olduğundan şekil paralelkenardır.'),
  ('Ardışık kenarları 8 cm ve 5 cm, aralarındaki açı 30° olan paralelkenarın alanı kaç cm²\'dir?', '20 cm²', ['40 cm²', '20√3 cm²', '10 cm²'], 'Paralelkenarın alanı a · b · sin α\'dır: 8 · 5 · (1/2) = 20 cm².'),
  ('Alanı 48 cm² olan bir paralelkenarın iki köşegeni çiziliyor. Oluşan dört üçgenden her birinin alanı kaç cm²\'dir?', '12 cm²', ['8 cm²', '16 cm²', '24 cm²'], 'Köşegenler birbirini ortaladığından oluşan dört üçgenin tabanları ve yükseklikleri ikişer ikişer eşit olur. Dördünün alanı da eşittir: 48 / 4 = 12 cm².'),
  ('Bir paralelkenarda ardışık iki açının açıortayları kesiştiğinde aralarındaki açı kaç derecedir?', '90°', ['45°', '60°', '120°'], 'Ardışık açılar bütünler olduğundan yarılarının toplamı 90°\'dir. Açıortaylarla oluşan üçgende üçüncü açı da 90° olur.'),
  ('Köşegenleri 10 cm ve 24 cm olan eşkenar dörtgenin bir kenarı kaç cm\'dir?', '13 cm', ['12 cm', '17 cm', '14,5 cm'], 'Eşkenar dörtgenin köşegenleri birbirini dik ortalar. Yarı köşegenler 5 ve 12 olduğundan kenar √(25 + 144) = 13 cm\'dir.'),
  ('Bir kenarı 6 cm ve bir iç açısı 60° olan eşkenar dörtgenin kısa köşegeni kaç cm\'dir?', '6 cm', ['3 cm', '6√3 cm', '6√2 cm'], 'Kısa köşegen 60°\'lik açının karşısındadır ve iki kenarla birlikte eşkenar üçgen oluşturur. Bu yüzden uzunluğu kenara eşittir.'),
  ('Eşkenar dörtgenin köşegenleri için aşağıdakilerden hangisi her zaman doğrudur?', 'Birbirini dik keser ve köşe açılarını ikiye böler.', ['Uzunlukları birbirine eşittir.', 'Birbirini keser ama ortalamaz.', 'Kenarlarla 45°\'lik açı yapar.'], 'Eşkenar dörtgen bir paralelkenar olduğundan köşegenler birbirini ortalar. Kenarlar eşit olduğu için köşegenler ayrıca diktir ve açıortaydır.'),
  ('Alanı 48 cm², çevresi 28 cm olan bir dikdörtgenin köşegeni kaç cm\'dir?', '10 cm', ['12 cm', '14 cm', '2√37 cm'], 'Kenarlar toplamı 14, çarpımı 48 olduğundan kenarlar 6 ve 8 cm\'dir. Köşegen √(36 + 64) = 10 cm olur.'),
  ('Her dikdörtgende bulunan ama her paralelkenarda bulunmayan köşegen özelliği hangisidir?', 'Köşegen uzunluklarının eşit olması', ['Köşegenlerin birbirini ortalaması', 'Köşegenlerin birbirine dik olması', 'Köşegenlerin açıortay olması'], 'Köşegenlerin birbirini ortalaması tüm paralelkenarlarda geçerlidir. Dikdörtgeni ayıran özellik köşegenlerin eşit uzunlukta olmasıdır.'),
  ('Uzun kenarı kısa kenarının 3 katı olan bir dikdörtgenin çevresi 64 cm\'dir. Alanı kaç cm²\'dir?', '192 cm²', ['128 cm²', '144 cm²', '256 cm²'], 'Kenarlar x ve 3x ise 2(4x) = 64 ve x = 8 olur. Kenarlar 8 ve 24 cm, alan 192 cm²\'dir.'),
  ('Ekranı 48 cm genişliğinde ve 36 cm yüksekliğinde olan bir televizyonun, ekran boyutu olarak bilinen çapraz uzunluğu kaç santimetredir?', '60 cm', ['54 cm', '72 cm', '84 cm'], 'Çapraz uzunluk dikdörtgenin köşegenidir: √(48² + 36²) = √3600 = 60 cm.'),
  ('Tabanları 10 cm ve 22 cm, yan kenarları 10 cm olan ikizkenar yamuğun alanı kaç cm²\'dir?', '128 cm²', ['96 cm²', '160 cm²', '220 cm²'], 'Taban farkının yarısı 6 cm\'dir. Yükseklik √(100 − 36) = 8 cm, alan (10 + 22)/2 · 8 = 128 cm² olur.'),
  ('İkizkenar yamukla ilgili aşağıdakilerden hangisi doğrudur?', 'Köşegenlerinin uzunlukları eşittir.', ['Köşegenleri birbirine diktir.', 'Tüm iç açıları eşittir.', 'Köşegenleri birbirini ortalar.'], 'İkizkenar yamukta aynı tabana komşu açılar eştir ve simetri nedeniyle köşegenler eşit uzunluktadır.'),
  ('Tabanları 7 cm ve 13 cm, yüksekliği 8 cm olan dik yamuğun eğik yan kenarı kaç cm\'dir?', '10 cm', ['8 cm', '12 cm', '√233 cm'], 'Eğik kenar, yatay farkı 13 − 7 = 6 cm ve dikey farkı 8 cm olan dik üçgenin hipotenüsüdür: √(36 + 64) = 10 cm.'),
  ('ABCD deltoidinde AB = AD ve CB = CD\'dir. A açısı 70°, C açısı 110° ise B açısı kaç derecedir?', '90°', ['70°', '100°', '110°'], 'Deltoitte simetri ekseni AC\'dir ve B ile D açıları eştir. (360 − 70 − 110)/2 = 90° olur.'),
  ('Yarıçapı 13 cm olan bir çemberde 24 cm uzunluğundaki kirişin merkeze uzaklığı kaç cm\'dir?', '5 cm', ['6 cm', '7 cm', '√145 cm'], 'Merkezden kirişe inilen dikme kirişi ortalar. Yarım kiriş 12 cm, yarıçap 13 cm olduğundan uzaklık √(169 − 144) = 5 cm bulunur.'),
  ('Yarıçapı 10 cm olan çemberin merkezine 6 cm uzaklıktaki bir kirişin uzunluğu kaç cm\'dir?', '16 cm', ['8 cm', '12 cm', '4√34 cm'], 'Yarım kiriş √(100 − 36) = 8 cm\'dir. Kirişin tamamı 16 cm olur.'),
  ('Aynı çemberde eşit uzunluktaki iki kiriş için hangisi doğrudur?', 'Merkeze uzaklıkları eşittir.', ['Birbirine her zaman paraleldir.', 'Birbirini her zaman dik keser.', 'Biri mutlaka çaptır.'], 'Merkezden kirişe dikme, yarıçap ve yarım kiriş bir dik üçgen oluşturur. Yarım kirişler eşitse dikmeler de eşit olur.'),
  ('Bir çemberde çapın uçlarını, çember üzerindeki başka bir noktayla birleştiren iki doğru parçası arasındaki açı kaç derecedir?', '90°', ['45°', '60°', '180°'], 'Bu açı yarım çemberi (180°\'lik yayı) gören bir çevre açıdır. Ölçüsü yayın yarısı, yani 90°\'dir. Bu sonuca Thales teoremi denir.'),
  ('Bir çemberde teğet ile değme noktasından çizilen kiriş arasındaki açı, 140°\'lik yayı görüyor. Bu açı kaç derecedir?', '70°', ['35°', '110°', '140°'], 'Teğet-kiriş açısı, gördüğü yayın yarısına eşittir: 140 / 2 = 70°.'),
  ('Çemberin içinde kesişen iki kiriş arasındaki bir açı ile ters açısı, 80° ve 40°\'lik yayları görüyor. Bu açı kaç derecedir?', '60°', ['40°', '120°', '20°'], 'İç açı, gördüğü iki yayın toplamının yarısıdır: (80 + 40) / 2 = 60°.'),
  ('Çember dışındaki bir P noktasından çizilen iki teğetin değme noktaları arasındaki küçük yay 120°\'dir. İki teğet arasındaki açı kaç derecedir?', '60°', ['30°', '90°', '120°'], 'Teğetler ve iki yarıçapın oluşturduğu dörtgende iki açı 90°\'dir. Merkez açı 120° olduğundan teğetler arası açı 360 − 180 − 120 = 60°\'dir.'),
  ('Bir çembere dıştan teğet olan ABCD dörtgeninde AB = 8 cm, BC = 9 cm ve CD = 11 cm\'dir. DA kaç cm\'dir?', '10 cm', ['9 cm', '12 cm', '10,5 cm'], 'Teğetler dörtgeninde karşılıklı kenar toplamları eşittir: AB + CD = BC + DA, yani 19 = 9 + DA ve DA = 10 cm olur.'),
  ('Yarıçapı 5 cm olan bir çemberin merkezine 13 cm uzaklıktaki bir noktadan çembere çizilen teğet parçasının uzunluğu kaç cm\'dir?', '12 cm', ['8 cm', '10 cm', '√194 cm'], 'Teğet yarıçapa dik olduğundan merkez, değme noktası ve dış nokta dik üçgen oluşturur: √(169 − 25) = 12 cm.'),
  ('Çember içindeki bir E noktasında kesişen AB ve CD kirişlerinde AE = 3, EB = 8 ve CE = 4 birimdir. ED kaç birimdir?', '6', ['5', '7', '10,5'], 'Kesişen kirişlerde AE · EB = CE · ED olur: 24 = 4 · ED ve ED = 6.'),
  ('Birbirine dıştan teğet olan iki çemberin ortak teğetlerinin sayısı kaçtır?', '3', ['1', '2', '4'], 'İki dış ortak teğet ve değme noktasından geçen bir iç ortak teğet vardır. Toplam 3 olur.'),
  ('Yarıçapı 9 cm olan bir çemberde 80°\'lik merkez açının gördüğü yayın uzunluğu kaç cm\'dir?', '4π cm', ['2π cm', '8π cm', '4,5π cm'], 'Yay uzunluğu 2πr · (α/360) ile bulunur: 18π · 80/360 = 4π cm.'),
  ('Yarıçapı 6 cm, merkez açısı 60° olan daire diliminin alanı kaç cm²\'dir?', '6π cm²', ['3π cm²', '12π cm²', '36π cm²'], 'Dilim alanı πr² · (α/360) ile hesaplanır: 36π · 1/6 = 6π cm².'),
  ('Yarıçapı 4 cm olan bir çemberde 2,5 radyanlık merkez açının gördüğü yay kaç cm\'dir?', '10 cm', ['5 cm', '8 cm', '6,25 cm'], 'Radyan tanımı gereği yay uzunluğu r · θ\'dır: 4 · 2,5 = 10 cm.'),
  ('Çevreleri oranı 2/3 olan iki dairenin alanları oranı kaçtır?', '4/9', ['2/3', '8/27', '√2/√3'], 'Çevreler yarıçaplarla, alanlar yarıçapların kareleriyle orantılıdır. Alan oranı (2/3)² = 4/9 olur.'),
  ('Çapı 70 cm olan bir bisiklet tekerleği 100 tam tur atıyor. π yerine 22/7 alınırsa bisiklet kaç metre yol alır?', '220 m', ['110 m', '154 m', '22,5 m'], 'Bir turda alınan yol çevreye eşittir: 70 · 22/7 = 220 cm. 100 turda 22 000 cm = 220 m yol alınır.'),
  ('Yarıçapı 5 cm olan bir çembere köşeleri çember üzerinde olacak biçimde yerleştirilen karenin alanı kaç cm²\'dir?', '50 cm²', ['25 cm²', '100 cm²', '25π cm²'], 'Karenin köşegeni çemberin çapına, yani 10 cm\'ye eşittir. Alan köşegenin karesinin yarısıdır: 100/2 = 50 cm².'),
  ('Bir kenarı 4 cm olan karenin içine, dört kenara da teğet bir daire çiziliyor. Karenin içinde kalıp dairenin dışında kalan bölgenin alanı kaç cm²\'dir?', '16 − 4π cm²', ['16 − 16π cm²', '16 − 2π cm²', '4π − 8 cm²'], 'İç teğet dairenin çapı kenara eşittir, yarıçapı 2 cm\'dir. 16 − π · 2² = 16 − 4π cm² bulunur.'),
  ('Uzunluğu 6 cm olan bir yelkovanın ucu 20 dakikada kaç cm\'lik yay çizer?', '4π cm', ['2π cm', '6π cm', '12π cm'], 'Yelkovan 60 dakikada tam tur atar. 20 dakika turun 1/3\'üdür: 2π · 6 / 3 = 4π cm.'),
  ('Bir daire diliminin çevresi, yarıçapı r ve yay uzunluğu l ise hangi ifadeyle bulunur?', '2r + l', ['r + l', '2πr + l', 'πr + l'], 'Daire dilimi iki yarıçap ve bir yay ile sınırlanır. Çevresi bu üç parçanın toplamıdır: 2r + l.'),
  ('Bir daire diliminin yarıçapı 3 katına çıkarılır, merkez açısı aynı bırakılırsa alanı kaç katına çıkar?', '9', ['3', '6', '27'], 'Dilim alanı πr² · α/360\'tır. Açı sabitken alan r² ile orantılıdır ve 3² = 9 katına çıkar.'),
  ('Yüzey alanı 150 cm² olan bir küpün hacmi kaç cm³\'tür?', '125 cm³', ['25 cm³', '216 cm³', '62,5 cm³'], 'Küpün altı eş kare yüzü vardır: 6a² = 150, a = 5 cm. Hacim a³ = 125 cm³ olur.'),
  ('Bir ayrıtı 6 cm olan küpün cisim köşegeninin uzunluğu kaç cm\'dir?', '6√3 cm', ['6√2 cm', '12 cm', '3√6 cm'], 'Küpün cisim köşegeni a√3 formülüyle bulunur: 6√3 cm.'),
  ('Boyutları 3 cm, 4 cm ve 12 cm olan dikdörtgenler prizmasının cisim köşegeni kaç cm\'dir?', '13 cm', ['12,5 cm', '15 cm', '19 cm'], 'Cisim köşegeni √(a² + b² + c²) ile bulunur: √(9 + 16 + 144) = √169 = 13 cm.'),
  ('İç ölçüleri 50 cm, 30 cm ve 40 cm olan dikdörtgenler prizması biçimindeki bir akvaryum tamamen doldurulursa kaç litre su alır?', '60 L', ['6 L', '120 L', '600 L'], 'Hacim 50 · 30 · 40 = 60 000 cm³\'tür. 1 L = 1000 cm³ olduğundan 60 L eder.'),
  ('Bir kenarının uzunluğu bilinmeyen küp biçimli bir kutunun bir yüzündeki köşegen 4√2 cm olarak ölçülüyor. Kutunun hacmi kaç cm³\'tür?', '64 cm³', ['32 cm³', '128√2 cm³', '16 cm³'], 'Yüzey köşegeni a√2 olduğundan a = 4 cm\'dir. Hacim 4³ = 64 cm³ olur.'),
  ('Tabanı dik kenarları 3 cm ve 4 cm olan dik üçgen, yüksekliği 10 cm olan dik üçgen prizmanın hacmi kaç cm³\'tür?', '60 cm³', ['120 cm³', '30 cm³', '70 cm³'], 'Prizmanın hacmi taban alanı ile yüksekliğin çarpımıdır: (3 · 4 / 2) · 10 = 60 cm³.'),
  ('Tabanı kenarları 3, 4 ve 5 cm olan üçgen, yüksekliği 10 cm olan dik prizmanın yanal alanı kaç cm²\'dir?', '120 cm²', ['60 cm²', '132 cm²', '112,5 cm²'], 'Dik prizmanın yanal alanı taban çevresi ile yüksekliğin çarpımıdır: 12 · 10 = 120 cm².'),
  ('Tabanı sekizgen olan bir prizmanın kaç ayrıtı vardır?', '24', ['16', '18', '32'], 'n-gen tabanlı prizmanın 3n ayrıtı vardır: iki tabanda n\'er tane ve yanlarda n tane. 3 · 8 = 24.'),
  ('Tabanı 40 cm × 30 cm olan dikdörtgenler prizması biçimindeki bir kaba 6 litre su eklenirse su seviyesi kaç cm yükselir?', '5 cm', ['2 cm', '6 cm', '7,5 cm'], '6 L = 6000 cm³\'tür. Yükselme 6000 / (40 · 30) = 5 cm olur.'),
  ('Yüzey alanının sayısal değeri hacminin sayısal değerine eşit olan küpün ayrıtı kaç birimdir?', '6', ['3', '4', '8'], '6a² = a³ eşitliğinden a = 6 bulunur.'),
  ('Ayrıtı 6 cm olan metal bir küp eritilerek ayrıtı 2 cm olan küçük küpler yapılıyor. Kayıp olmadığına göre kaç küçük küp elde edilir?', '27', ['3', '9', '36'], 'Hacim korunur: 216 / 8 = 27 küçük küp elde edilir.'),
  ('Taban yarıçapı 4 cm, yüksekliği 5 cm olan silindirin yanal alanı kaç cm²\'dir?', '40π cm²', ['20π cm²', '80π cm²', '22,5π cm²'], 'Yanal yüzey açıldığında boyu 2πr, eni h olan bir dikdörtgen olur: 2π · 4 · 5 = 40π cm².'),
  ('Taban yarıçapı 2 cm, yüksekliği 3 cm olan kapalı bir silindirin toplam yüzey alanı kaç cm²\'dir?', '20π cm²', ['12π cm²', '16π cm²', '20,5π cm²'], 'Yanal alan 2πrh = 12π, iki taban 2πr² = 8π cm²\'dir. Toplam 20π cm² olur.'),
  ('Eksenel kesiti kare olan bir silindirin taban yarıçapı 3 cm ise hacmi kaç cm³\'tür?', '54π cm³', ['27π cm³', '18π cm³', '108π cm³'], 'Eksenel kesit, kenarları 2r ve h olan dikdörtgendir. Kare olduğundan h = 2r = 6 cm ve V = π · 9 · 6 = 54π cm³ olur.'),
  ('Taban yarıçapı 10 cm olan silindir biçimli, içinde su bulunan bir kaba bir taş atılıyor ve taş tamamen batınca su seviyesi 2 cm yükseliyor. Taşın hacmi kaç cm³\'tür?', '200π cm³', ['20π cm³', '40π cm³', '400π cm³'], 'Yükselen suyun hacmi taşın hacmine eşittir: π · 10² · 2 = 200π cm³.'),
  ('Bir parti şapkası, taban yarıçapı 3 cm ve yüksekliği 4 cm olan dik koni biçimindedir. Tabanı açık olan bu şapkanın yapımında kaç cm² karton kullanılmıştır?', '15π cm²', ['12π cm²', '24π cm²', '9π cm²'], 'Ana doğru √(9 + 16) = 5 cm\'dir. Yanal alan πrl = π · 3 · 5 = 15π cm² olur.'),
  ('Taban yarıçapı 5 cm, ana doğrusu 13 cm olan dik koninin toplam yüzey alanı kaç cm²\'dir?', '90π cm²', ['65π cm²', '25π cm²', '78π cm²'], 'Taban alanı 25π, yanal alan π · 5 · 13 = 65π cm²\'dir. Toplam 90π cm² olur.'),
  ('Dik kenarları 3 cm ve 4 cm olan bir dik üçgen, 4 cm\'lik dik kenarı etrafında 360° döndürülüyor. Oluşan cismin hacmi kaç cm³\'tür?', '12π cm³', ['16π cm³', '36π cm³', '37,5π cm³'], 'Dönme sonucunda yarıçapı 3 cm, yüksekliği 4 cm olan bir koni oluşur: (1/3) · π · 9 · 4 = 12π cm³.'),
  ('Eni 2 cm, boyu 5 cm olan dikdörtgen biçimli bir kâğıt, uzun kenarı bir mil gibi sabit tutularak tam tur çevrilirse süpürdüğü cismin hacmi kaç cm³ olur?', '20π cm³', ['50π cm³', '10π cm³', '12,5π cm³'], 'Dönme ekseni olan kenar yüksekliği, diğer kenar yarıçapı verir. Silindirin hacmi π · 4 · 5 = 20π cm³ olur.'),
  ('Koni biçimindeki bir külahın taban yarıçapı ve yüksekliği ikişer katına çıkarılırsa hacmi kaç katına çıkar?', '8', ['2', '4', '6'], 'Hacim r²h ile orantılıdır: 2² · 2 = 8 katına çıkar.'),
  ('Bir kürenin dış yüzeyinin alanı 64π cm² olarak ölçülmüştür. Bu kürenin kapladığı hacim kaç cm³\'tür?', '256π/3 cm³', ['64π cm³', '128π/3 cm³', '256π cm³'], '4πr² = 64π ise r = 4 cm olur. Hacim (4/3)π · 64 = 256π/3 cm³ bulunur.'),
  ('İç yarıçapı 6 cm olan yarım küre biçimindeki bir kase ağzına kadar kaç cm³ su alır?', '144π cm³', ['288π cm³', '72π cm³', '216,5π cm³'], 'Yarım kürenin hacmi kürenin yarısıdır: (1/2) · (4/3)π · 216 = 144π cm³.'),
  ('Ayrıtı 10 cm olan bir küpün içine, küpün bütün yüzlerine teğet olacak biçimde yerleştirilen kürenin hacmi kaç cm³\'tür?', '500π/3 cm³', ['1000π/3 cm³', '4000π/3 cm³', '100π cm³'], 'Kürenin çapı küpün ayrıtına eşittir, r = 5 cm\'dir. Hacim (4/3)π · 125 = 500π/3 cm³ olur.'),
  ('Yarıçapı 13 cm olan bir küre, merkezden 5 cm uzaklıktaki bir düzlemle kesiliyor. Oluşan kesitin alanı kaç cm²\'dir?', '144π cm²', ['169π cm²', '64π cm²', '120,25π cm²'], 'Kesit bir dairedir. Yarıçapı √(169 − 25) = 12 cm\'dir ve alanı 144π cm² olur.'),
  ('Yarıçapı 6 cm olan metal bir küre eritilerek yarıçapı 2 cm olan bilyeler yapılıyor. Kaç bilye elde edilir?', '27', ['3', '9', '36'], 'Hacimler oranı yarıçaplar oranının küpüdür: (6/2)³ = 27.'),
  ('Bir koni, yüksekliğinin tam ortasından tabana paralel bir düzlemle kesiliyor. Üstte kalan küçük koninin hacmi, ilk koninin hacminin kaçta kaçıdır?', '1/8', ['1/2', '1/4', '1/6'], 'Küçük koni büyük koniye 1/2 oranında benzerdir. Hacimler oranı (1/2)³ = 1/8 olur.'),
  ('Dışbükey bir çok yüzlünün 12 köşesi ve 30 ayrıtı vardır. Bu cismin kaç yüzü vardır?', '20', ['16', '18', '22'], 'Euler formülüne göre Y = 2 − K + A = 2 − 12 + 30 = 20 olur. Bu değerler düzgün yirmiyüzlüye aittir.'),
  ('Düzgün onikiyüzlünün (dodekahedron) yüzleri hangi çokgendir?', 'Düzgün beşgen', ['Eşkenar üçgen', 'Kare', 'Düzgün altıgen'], 'Onikiyüzlünün 12 yüzünün her biri düzgün beşgendir. Her köşede üç beşgen buluşur.'),
  ('Düzgün sekizyüzlünün (oktahedron) kaç köşesi vardır?', '6', ['8', '10', '12'], 'Sekizyüzlünün 8 eşkenar üçgen yüzü, 12 ayrıtı ve 6 köşesi vardır: 6 − 12 + 8 = 2.'),
  ('Aşağıdaki cisimlerden hangisi bir Platon cismi değildir?', 'Kare piramit', ['Düzgün dörtyüzlü', 'Küp', 'Düzgün sekizyüzlü'], 'Platon cisminin tüm yüzleri eş düzgün çokgen olmalıdır. Kare piramidin tabanı kare, yan yüzleri üçgendir.'),
  ('Platon cisimlerinden kaç tanesinin yüzleri eşkenar üçgendir?', '3', ['1', '2', '4'], 'Dörtyüzlü, sekizyüzlü ve yirmiyüzlünün yüzleri eşkenar üçgendir. Küpün yüzleri kare, onikiyüzlününki beşgendir.'),
  ('Uzunluğu 10 cm olan bir doğru parçası bir düzlemle 60°\'lik açı yapıyor. Bu doğru parçasının düzlem üzerindeki dik izdüşümünün uzunluğu kaç cm\'dir?', '5 cm', ['5√3 cm', '10 cm', '5√2 cm'], 'İzdüşüm uzunluğu, uzunluk ile açının kosinüsünün çarpımıdır: 10 · cos 60° = 5 cm.'),
  ('x ekseni üzerinde olup A(1, 3) ve B(5, 1) noktalarına eşit uzaklıkta bulunan nokta hangisidir?', '(2, 0)', ['(3, 0)', '(1, 0)', '(2,5, 0)'], '(x − 1)² + 9 = (x − 5)² + 1 denkleminden 8x = 16 ve x = 2 bulunur.'),
  ('AB doğru parçasının orta noktası M(3, 4) ve A(1, 1) ise B noktasının koordinatları nedir?', '(5, 7)', ['(2, 2,5)', '(4, 6)', '(7, 5)'], 'B = 2M − A = (6 − 1, 8 − 1) = (5, 7) olur.'),
  ('A(0, 0) ve B(9, 6) noktalarını birleştiren doğru parçasını A\'dan başlayarak 1 : 2 oranında bölen nokta hangisidir?', '(3, 2)', ['(6, 4)', '(4,5, 3)', '(2, 3)'], 'Bölen nokta A + (1/3)(B − A) = (3, 2) olur.'),
  ('A(1, 2), B(3, 6) ve C(5, k) noktaları aynı doğru üzerinde ise k kaçtır?', '10', ['8', '9', '12,5'], 'AB\'nin eğimi (6 − 2)/(3 − 1) = 2\'dir. BC\'nin eğimi de 2 olmalıdır: (k − 6)/2 = 2, k = 10.'),
  ('Köşeleri A(0, 0), B(6, 0) ve C(3, 3√3) olan üçgen hangi türdendir?', 'Eşkenar üçgen', ['Dik üçgen', 'Çeşitkenar üçgen', 'Geniş açılı ikizkenar üçgen'], 'AB = 6, AC = √(9 + 27) = 6 ve BC = √(9 + 27) = 6 olduğundan üç kenar eşittir.'),
  ('Pozitif x ekseniyle 60°\'lik açı yapan bir doğrunun eğimi kaçtır?', '√3', ['1/2', '√3/3', '1'], 'Eğim, doğrunun x ekseniyle pozitif yönde yaptığı açının tanjantıdır: tan 60° = √3.'),
  ('3x + 4y = 12 doğrusu ile koordinat eksenleri arasında kalan üçgensel bölgenin alanı kaç birimkaredir?', '6', ['7', '12', '3,5'], 'x = 0 için y = 3, y = 0 için x = 4 olur. Eksenlerle oluşan dik üçgenin alanı 4 · 3 / 2 = 6\'dır.'),
  ('(1, 2) noktasının 3x + 4y − 1 = 0 doğrusuna uzaklığı kaç birimdir?', '2', ['1', '3', '2,5'], 'Uzaklık ∣ax₀ + by₀ + c∣ / √(a² + b²) formülüyle bulunur: ∣3 + 8 − 1∣ / 5 = 2.'),
  ('Eksenleri (3, 0) ve (0, 4) noktalarında kesen doğrunun denklemi hangisidir?', '4x + 3y = 12', ['3x + 4y = 12', '4x − 3y = 12', '3x + 4y = 7'], 'Eksen kesişimleri a ve b olan doğru x/a + y/b = 1 biçimindedir: x/3 + y/4 = 1, yani 4x + 3y = 12.'),
  ('x = 4 doğrusunun eğimi için hangisi doğrudur?', 'Tanımsızdır.', ['0\'dır.', '4\'tür.', '1\'dir.'], 'x = 4 düşey bir doğrudur. Üzerindeki iki noktanın apsisleri farkı 0 olduğundan eğim kesri tanımsız olur.'),
  ('ax + 2y = 5 doğrusu y = 3x doğrusuna paralel ise a kaçtır?', '−6', ['6', '−3/2', '3/2'], 'ax + 2y = 5 doğrusunun eğimi −a/2\'dir. Paralellik için −a/2 = 3 olmalıdır, buradan a = −6.'),
  ('y = x, y = −x + 4 doğruları ve x ekseni arasında kalan üçgensel bölgenin alanı kaç birimkaredir?', '4', ['2', '8', '3,5'], 'Doğrular (2, 2)\'de kesişir. y = −x + 4 x eksenini (4, 0)\'da keser. Taban 4, yükseklik 2 olduğundan alan 4\'tür.'),
  ('Eğimi negatif olan bir doğru, x ekseniyle pozitif yönde nasıl bir açı yapar?', 'Geniş açı', ['Dar açı', 'Dik açı', 'Sıfır derecelik açı'], 'Eğim tan α\'dır ve 0° ile 180° arasında tan α < 0 olması için α\'nın 90° ile 180° arasında olması gerekir.'),
  ('Köşeleri O(0, 0), A(4, 0) ve B(0, 6) olan üçgenin AB kenarına ait kenarortayı hangi noktadan geçer?', '(2, 3)', ['(4, 6)', '(2, 0)', '(0, 1,5)'], 'Kenarortay O köşesinden AB\'nin orta noktasına uzanır. Orta nokta ((4 + 0)/2, (0 + 6)/2) = (2, 3)\'tür.'),
  ('(2, 5) noktası orijin etrafında saat yönünün tersine 90° döndürülürse hangi noktaya gelir?', '(−5, 2)', ['(5, −2)', '(−2, 5)', '(−5, −2)'], 'Saat yönünün tersine 90° dönmede (x, y) noktası (−y, x) noktasına gider: (−5, 2).'),
  ('Düzlemde x = 2 doğrusu bir ayna gibi düşünülürse, (5, 3) noktasının bu aynadaki görüntüsünün koordinatları ne olur?', '(−1, 3)', ['(5, −1)', '(−5, 3)', '(2, 3)'], 'Nokta doğrunun 3 birim sağındadır. Yansıması 3 birim solda, yani x = −1\'dedir; ordinat değişmez.'),
  ('Aşağıdaki dönüşümlerden hangisi şeklin uzunluklarını genel olarak korumaz?', 'Katsayısı 2 olan homotet', ['Öteleme', 'Bir doğruya göre yansıma', 'Bir nokta etrafında dönme'], 'Öteleme, yansıma ve dönme uzunlukları koruyan izometrilerdir. Katsayısı 2 olan homotet ise tüm uzunlukları iki katına çıkarır.'),
  ('Merkezi orijin, katsayısı 3 olan bir homotet bir üçgene uygulanırsa üçgenin alanı kaç katına çıkar?', '9', ['3', '6', '27'], 'Homotet uzunlukları 3 katına çıkarır. Alan uzunlukların karesiyle orantılı olduğundan 3² = 9 katına çıkar.'),
  ('Kare olmayan bir dikdörtgenin kaç simetri ekseni vardır?', '2', ['0', '1', '4'], 'Karşılıklı kenarların orta noktalarından geçen iki doğru simetri eksenidir. Köşegenler eksen değildir, çünkü kenarlar eşit değildir.'),
  ('Düzgün bir beşgeni kendisiyle çakıştıran en küçük pozitif dönme açısı kaç derecedir?', '72°', ['36°', '60°', '108°'], 'Düzgün n-gen 360°/n\'lik dönmede kendisiyle çakışır: 360 / 5 = 72°.'),
  ('Büyük Latin harflerinden hangisinin hem yatay hem düşey simetri ekseni vardır?', 'H', ['A', 'B', 'N'], 'H harfi hem dikey hem yatay eksene göre simetriktir. A yalnız dikey, B yalnız yatay eksene göre simetriktir. N\'nin simetri ekseni yoktur.'),
  ('(a, b) noktası önce y eksenine göre yansıtılıyor, sonra elde edilen nokta x eksenine göre yansıtılıyor. Son nokta hangisidir?', '(−a, −b)', ['(a, −b)', '(−a, b)', '(b, a)'], 'y eksenine göre yansıma (−a, b), ardından x eksenine göre yansıma (−a, −b) verir. Sonuç orijine göre simetriktir.'),
  ('x² + y² − 6x + 4y − 12 = 0 çemberinin yarıçapı kaç birimdir?', '5', ['4', '√12', '6'], 'Tam kareye tamamlanırsa (x − 3)² + (y + 2)² = 12 + 9 + 4 = 25 olur, yarıçap 5\'tir.'),
  ('P(5, 1) noktası x² + y² = 25 çemberine göre nerededir?', 'Çemberin dışında', ['Çemberin içinde', 'Çemberin üzerinde', 'Çemberin merkezinde'], '5² + 1² = 26 > 25 olduğundan noktanın merkeze uzaklığı yarıçaptan büyüktür.'),
  ('Merkezi (3, −4) olan ve x eksenine teğet olan çemberin yarıçapı kaç birimdir?', '4', ['3', '5', '3,5'], 'x eksenine teğet çemberde yarıçap merkezin x eksenine uzaklığına, yani ordinatın mutlak değerine eşittir: 4.'),
  ('Merkezi (0, 2) ve yarıçapı 5 olan çembere, merkezin üstünde kalan hangi yatay doğru teğettir?', 'y = 7', ['y = 5', 'y = 3', 'y = 10'], 'Yatay teğet doğru merkezden yarıçap kadar uzaktadır: 2 + 5 = 7.'),
  ('Öklid\'in beşinci postülatı hangi kavramla ilgilidir?', 'Paralel doğrular', ['Çemberin çizilmesi', 'Dik açıların eşliği', 'İki noktadan doğru geçmesi'], 'Beşinci postülat, bir doğruya dışındaki bir noktadan tek paralel çizilebileceği biçiminde de ifade edilir. Bu postülatın reddi Öklid dışı geometrileri doğurmuştur.'),
  ('1 : 100 ölçekli bir mimari maketteki alanların gerçek alanlara oranı kaçtır?', '1 : 10 000', ['1 : 100', '1 : 1000', '1 : 1 000 000'], 'Uzunluk oranı 1/100 ise alanlar oranı (1/100)² = 1/10 000 olur.'),
  ('Bir ev planında 1 cm, gerçekte 2 m\'yi gösteriyor. Planda 3 cm × 4 cm olan dikdörtgen bir odanın gerçek alanı kaç m²\'dir?', '48 m²', ['12 m²', '24 m²', '96,5 m²'], 'Gerçek boyutlar 6 m ve 8 m\'dir. Alan 6 · 8 = 48 m² olur.'),
  ('Gerçekte 30 km olan bir yol, 1 : 200 000 ölçekli haritada kaç cm uzunluğunda gösterilir?', '15 cm', ['1,5 cm', '6 cm', '150 cm'], '30 km = 3 000 000 cm\'dir. Bu değer 200 000\'e bölünürse 15 cm bulunur.'),
  ('Bir öğrenci kenar uzunlukları 2 cm, 3 cm ve 6 cm olan bir üçgenin alanını Heron formülüyle bulmaya çalışıyor. Bu çalışmayla ilgili en doğru değerlendirme hangisidir?', 'Böyle bir üçgen olamayacağı için hesap anlamsızdır.', ['Alan 6 cm² olarak bulunur.', 'Önce yükseklik hesaplanırsa alan bulunur.', 'Alan negatif çıkar ama mutlak değeri alınır.'], '2 + 3 = 5 < 6 olduğundan üçgen eşitsizliği sağlanmaz. Bu kenarlarla bir üçgen kurulamaz.'),
  ('Çevrel çemberinin merkezi kenarlarından birinin üzerinde bulunan bir üçgen hangi türdendir?', 'Dik üçgen', ['Eşkenar üçgen', 'Geniş açılı üçgen', 'Dar açılı ikizkenar üçgen'], 'Merkez bir kenarın üzerindeyse o kenar çaptır. Çapı gören çevre açı 90° olduğundan üçgen diktir.'),
  ('Bir kenarı 6 cm olan eşkenar üçgenin çevrel çemberinin yarıçapı kaç cm\'dir?', '2√3 cm', ['√3 cm', '3√3 cm', '3 cm'], 'Eşkenar üçgende çevrel merkez ağırlık merkeziyle çakışır. R, yüksekliğin (3√3) üçte ikisidir: 2√3 cm.'),
  ('Bir eşkenar üçgenin çevrel çemberinin yarıçapı, iç teğet çemberinin yarıçapının kaç katıdır?', '2', ['√2', '√3', '3'], 'İki merkez de ağırlık merkezidir. Ağırlık merkezi yüksekliği 2 : 1 oranında böldüğünden R = 2r olur.'),
  ('Ortak bir BC tabanına sahip ABC ve DBC üçgenlerinde A ve D köşeleri BC\'ye paralel bir doğru üzerindedir. Bu iki üçgenin alanları için ne söylenebilir?', 'Alanları eşittir.', ['A ile D\'nin BC\'ye uzaklığına göre değişir.', 'ABC\'nin alanı her zaman daha büyüktür.', 'Alanları oranı AB/DC\'dir.'], 'Paralel doğrular arası uzaklık sabittir. Taban ve yükseklik ortak olduğundan alanlar eşittir.'),
  ('ABC üçgeninde DE ∥ BC\'dir (D, AB; E, AC üzerinde). AD = 3, AE = 4 ve EC = 8 ise DB kaçtır?', '6', ['4', '5', '32/3'], 'Temel orantı teoremine göre AD/DB = AE/EC\'dir: 3/DB = 4/8 ve DB = 6.'),
  ('Bir dik üçgende dik köşeden hipotenüse çizilen yükseklik, üçgeni iki küçük üçgene ayırır. Bu üçgenlerle ilgili hangisi doğrudur?', 'İkisi de birbirine ve büyük üçgene benzerdir.', ['Birbirine eştirler.', 'Yalnız biri büyük üçgene benzerdir.', 'Alanları her zaman eşittir.'], 'Her küçük üçgen büyük üçgenle bir dar açıyı ve dik açıyı paylaşır. AA benzerliği gereği üç üçgen de birbirine benzerdir. Öklid bağıntıları buradan çıkar.'),
  ('İki üçgende karşılıklı iki kenar orantılı ve bu kenarlar arasındaki açılar eşse üçgenler hakkında ne söylenebilir?', 'Benzerdirler.', ['Eştirler.', 'Alanları eşittir.', 'Benzer olup olmadıkları bilinemez.'], 'Bu durum KAK benzerlik kuralıdır. Orantı katsayısı 1 değilse üçgenler eş değil, yalnız benzerdir.'),
  ('Bir öğrenci, "Kenarları 7, 24 ve 25 olan üçgenin en büyük açısı geniştir" diyor. Bu ifade için doğru değerlendirme hangisidir?', 'Yanlıştır, en büyük açı tam 90°\'dir.', ['Doğrudur, 25 en uzun kenardır.', 'Yanlıştır, üçgen dar açılıdır.', 'Böyle bir üçgen oluşmaz.'], '7² + 24² = 49 + 576 = 625 = 25² olduğundan üçgen diktir, en büyük açı 90°\'dir.'),
  ('Bir ABC üçgeninde AB = AC ve A açısı 60° ise bu üçgen için en doğru sınıflandırma hangisidir?', 'Eşkenar üçgen', ['Yalnız ikizkenar, eşkenar olmayan üçgen', 'Dik üçgen', 'Geniş açılı üçgen'], 'Taban açıları (180 − 60)/2 = 60° olur. Üç açı da 60° olduğundan üç kenar da eşittir.'),
  ('Bir üçgenin ağırlık merkezi, diklik merkezi ve çevrel çember merkezinin aynı noktada bulunması için üçgen hangi türden olmalıdır?', 'Eşkenar', ['Dik', 'Çeşitkenar dar açılı', 'Geniş açılı ikizkenar'], 'Eşkenar üçgende kenarortaylar, yükseklikler, açıortaylar ve kenar orta dikmeler aynı doğrulardır. Bu yüzden bütün merkezler çakışır.'),
  ('Bir çemberde AB çap ve C çember üzerinde bir noktadır. CAB açısı 25° ise ABC açısı kaç derecedir?', '65°', ['25°', '55°', '77,5°'], 'C köşesindeki açı çapı gördüğünden 90°\'dir. ABC = 180 − 90 − 25 = 65° olur.'),
  ('Bir çembere içten çizilmiş ABC üçgeninde A açısı 50°\'dir. BC kirişinin A\'yı içermeyen yayı kaç derecedir?', '100°', ['50°', '130°', '112,5°'], 'A açısı bir çevre açıdır ve gördüğü yay, kendisinin iki katıdır: 2 · 50 = 100°.'),
  ('ABCD kirişler dörtgeninde A açısı 3x, C açısı 2x ise A açısı kaç derecedir?', '108°', ['72°', '90°', '112,5°'], 'Karşılıklı açılar bütünler olduğundan 5x = 180 ve x = 36 olur. A = 108° bulunur.'),
  ('Yarıçapı 7 cm olan çembere içten çizilen düzgün altıgenin çevresi kaç cm\'dir?', '42 cm', ['21 cm', '42√3 cm', '84 cm'], 'Düzgün altıgen merkezden altı eşkenar üçgene ayrılır. Kenarı yarıçapa eşittir ve çevre 6 · 7 = 42 cm olur.'),
  ('Bir öğrenci "Çevre açı her zaman dar açıdır." diyor. Bu ifade için doğru değerlendirme hangisidir?', 'Yanlıştır, büyük yayı gören çevre açı geniş olabilir.', ['Doğrudur, çevre açı en çok 90° olur.', 'Doğrudur, çevre açı merkez açının yarısıdır.', 'Yanlıştır, çevre açı her zaman diktir.'], 'Çevre açı gördüğü yayın yarısıdır. Örneğin 240°\'lik yayı gören çevre açı 120° olur ve geniştir.'),
  ('Kare biçimli bir peçete, dört köşesi 8 cm çaplı dairesel bir tabağın kenarına değecek biçimde tabağa yerleştiriliyor. Peçetenin bir kenarı kaç cm\'dir?', '4√2 cm', ['4 cm', '8 cm', '2√2 + 2 cm'], 'Karenin köşegeni çapa (8 cm) eşittir. Kenar köşegenin √2\'ye bölümüdür: 8/√2 = 4√2 cm.'),
  ('Bir çemberde aynı uzunluktaki iki kirişin gördüğü merkez açılar için hangisi doğrudur?', 'Eşittirler.', ['Toplamları 180°\'dir.', 'Biri diğerinin iki katıdır.', 'Kirişlerin konumuna göre her ilişki olabilir.'], 'Kirişin uçları ve merkez ikizkenar üçgen oluşturur. Eş kirişlerle oluşan üçgenler KKK kuralıyla eş olduğundan merkez açılar eşittir.'),
  ('Bir çemberde merkez açısı 90° olan kirişin uzunluğu 10 cm ise çemberin yarıçapı kaç cm\'dir?', '5√2 cm', ['5 cm', '10 cm', '10√2 cm'], 'Kiriş ile iki yarıçap ikizkenar dik üçgen oluşturur. Kiriş hipotenüs olduğundan r = 10/√2 = 5√2 cm\'dir.'),
  ('Merkez açısı 60° olan bir kirişin uzunluğu çemberin yarıçapına göre nasıldır?', 'Yarıçapa eşittir.', ['Yarıçapın yarısıdır.', 'Yarıçapın √2 katıdır.', 'Yarıçapın √3 katıdır.'], 'İki yarıçap ile kiriş, tepe açısı 60° olan ikizkenar üçgen oluşturur. Taban açıları da 60° olduğundan üçgen eşkenardır.'),
  ('Her kenarı 10 cm olan menteşeli kare bir çerçeve, açılarından biri 30° olacak biçimde yamultuluyor. Çerçevenin sınırladığı bölgenin alanı kaç cm²\'dir?', '50 cm²', ['100 cm²', '50√3 cm²', '25 cm²'], 'Eşkenar dörtgen bir paralelkenar olduğundan alanı a² · sin α ile bulunur: 100 · (1/2) = 50 cm².'),
  ('Kenarları 6 cm ve 8 cm olan bir dikdörtgenin dört köşesinden geçen çemberin sınırladığı dairenin alanı kaç cm²\'dir?', '25π cm²', ['100π cm²', '48π cm²', '12,5π cm²'], 'Dikdörtgenin köşegeni çemberin çapıdır: √(36 + 64) = 10 cm. Yarıçap 5 cm, alan 25π cm² olur.'),
  ('ABCD karesinin bir kenarı 6 cm\'dir. E noktası BC kenarı üzerinde herhangi bir noktadır. AED üçgeninin alanı kaç cm²\'dir?', '18 cm²', ['9 cm²', '12 cm²', 'E\'nin yerine göre değişir.'], 'AD tabanı 6 cm\'dir ve E\'nin AD\'ye uzaklığı her zaman karenin kenarı olan 6 cm\'dir. Alan 6 · 6 / 2 = 18 cm² olur.'),
  ('Bir karenin köşegeni üzerine çizilen yeni karenin alanı, ilk karenin alanının kaç katıdır?', '2', ['√2', '3', '4'], 'Köşegen a√2 olduğundan yeni karenin alanı (a√2)² = 2a² olur.'),
  ('Bir dikdörtgenin uzun kenarı %25 artırılıp kısa kenarı %20 azaltılırsa alanı nasıl değişir?', 'Değişmez.', ['%5 artar.', '%5 azalır.', '%45 artar.'], 'Yeni alan 1,25 · 0,8 = 1 katıdır. Alan aynı kalır.'),
  ('Bir paralelkenarın iki kenarı 9 cm ve 12 cm\'dir. Kısa kenara ait yükseklik 8 cm ise uzun kenara ait yükseklik kaç cm\'dir?', '6 cm', ['8 cm', '10,5 cm', '4 cm'], 'Alan her iki taban için aynıdır: 9 · 8 = 72 cm². Uzun kenara ait yükseklik 72 / 12 = 6 cm olur.'),
  ('Ayrıtı 6 cm olan bir küpün alt yüzü taban, üst yüzünün merkezi tepe noktası olan piramidin hacmi kaç cm³\'tür?', '72 cm³', ['36 cm³', '108 cm³', '216 cm³'], 'Piramidin taban alanı 36 cm², yüksekliği 6 cm\'dir. Hacim 36 · 6 / 3 = 72 cm³ olur.'),
  ('Bir öğrenci "Silindirin taban yarıçapını iki katına çıkarırsam hacmi de iki katına çıkar." diyor. Bu ifade için doğru değerlendirme hangisidir?', 'Yanlıştır, hacim 4 katına çıkar.', ['Doğrudur, hacim yarıçapla doğru orantılıdır.', 'Yanlıştır, hacim 8 katına çıkar.', 'Yanlıştır, hacim değişmez.'], 'Hacim πr²h olduğundan yarıçapın karesiyle orantılıdır. Yarıçap 2 katına çıkarsa hacim 4 katına çıkar.'),
  ('Tabanı bir kenarı 4 cm olan eşkenar üçgen, yüksekliği 5 cm olan dik prizmanın hacmi kaç cm³\'tür?', '20√3 cm³', ['40√3 cm³', '10√3 cm³', '80 cm³'], 'Taban alanı 16√3/4 = 4√3 cm²\'dir. Hacim 4√3 · 5 = 20√3 cm³ olur.'),
  ('Taban yarıçapı 6 cm olan bir silindirin hacmi, yarıçapı 6 cm olan kürenin hacmine eşittir. Silindirin yüksekliği kaç cm\'dir?', '8 cm', ['6 cm', '12 cm', '4,5 cm'], 'πr²h = (4/3)πr³ ise h = 4r/3 = 8 cm olur.'),
  ('Taban yarıçapı 6 cm, ana doğrusu 10 cm olan dik koninin hacmi kaç cm³\'tür?', '96π cm³', ['120π cm³', '288π cm³', '60π cm³'], 'Yükseklik √(100 − 36) = 8 cm\'dir. Hacim (1/3) · π · 36 · 8 = 96π cm³ olur.'),
  ('Tabanının bir kenarı 10 cm olan kare dik piramidin yan yüz yüksekliği 13 cm ise piramidin yüksekliği kaç cm\'dir?', '12 cm', ['√69 cm', '8 cm', '13,5 cm'], 'Yan yüz yüksekliği, piramit yüksekliği ve taban kenarının yarısı (5 cm) bir dik üçgen oluşturur: √(169 − 25) = 12 cm.'),
  ('Bir silindirin yüksekliği yarıya indirilip yarıçapı iki katına çıkarılırsa hacmi kaç katına çıkar?', '2', ['1', '4', '8'], 'Yeni hacim π(2r)²(h/2) = 2πr²h olur, yani hacim 2 katına çıkar.'),
  ('İç ölçüleri 20 cm, 10 cm ve 8 cm olan dikdörtgenler prizması biçimli bir kap, 10 cm × 8 cm\'lik yüzü taban olacak biçimde dikiliyor. Kaptaki 960 cm³ su ne kadar yüksekliğe ulaşır?', '12 cm', ['4,8 cm', '6 cm', '9,6 cm'], 'Taban alanı 10 · 8 = 80 cm²\'dir. Su yüksekliği 960 / 80 = 12 cm olur.'),
  ('İki açının komşu açı olması için hangi koşul gereklidir?', 'Köşeleri ve birer kenarları ortak, iç bölgeleri ayrık olmalıdır.', ['Ölçüleri toplamı 180° olmalıdır.', 'Ölçüleri birbirine eşit olmalıdır.', 'Köşeleri ortak olup kenarları ters yönlü olmalıdır.'], 'Komşu açılar aynı köşeyi ve bir kenarı paylaşır, iç bölgeleri üst üste gelmez. Toplamlarının 180° olması gerekmez.'),
  ('135°\'lik açının radyan cinsinden ölçüsü hangisidir?', '3π/4', ['2π/3', '5π/6', 'π/4'], 'Derece, π/180 ile çarpılarak radyana çevrilir: 135 · π/180 = 3π/4.'),
  ('Bir açının ölçüsü, bütünlerinin ölçüsünün 3/2 katıdır. Bu açı kaç derecedir?', '108°', ['72°', '120°', '112,5°'], 'x = (3/2)(180 − x) ise 2x = 540 − 3x, 5x = 540 ve x = 108° olur.'),
  ('İki paralel doğruyu kesen bir doğru ile oluşan dış ters açılardan biri 2x + 15°, diğeri 3x − 25° ise x kaçtır?', '40', ['32', '38', '42,5'], 'Dış ters açılar eşittir: 2x + 15 = 3x − 25 ve x = 40 olur.'),
  ('Bir dik üçgende hipotenüs 25 cm\'dir. Dik kenarlardan birinin hipotenüs üzerindeki dik izdüşümü 9 cm ise bu dik kenar kaç cm\'dir?', '15 cm', ['12 cm', '16 cm', '3√34 cm'], 'Öklid bağıntısına göre dik kenarın karesi, izdüşümü ile hipotenüsün çarpımıdır: 9 · 25 = 225, kenar 15 cm olur.'),
  ('Bir dik üçgende hipotenüse ait yükseklik 12 cm\'dir ve hipotenüs üzerinde ayırdığı parçalardan biri 9 cm\'dir. Hipotenüs kaç cm\'dir?', '25 cm', ['16 cm', '21 cm', '27,5 cm'], 'h² = p · k ise 144 = 9 · k ve k = 16 cm olur. Hipotenüs 9 + 16 = 25 cm\'dir.'),
  ('tan 30° · tan 60° çarpımı kaçtır?', '1', ['√3', '1/3', '3'], 'tan 30° = √3/3 ve tan 60° = √3\'tür. Çarpım 3/3 = 1 olur. Tümler iki açının tanjantları çarpımı her zaman 1\'dir.'),
  ('Dar açılı bir dik üçgende bir açının kosinüsü ile diğer dar açının sinüsü arasındaki ilişki hangisidir?', 'Birbirine eşittir.', ['Toplamları 1\'dir.', 'Çarpımları 1\'dir.', 'Biri diğerinin karesidir.'], 'İki dar açı tümlerdir. Bir açının komşu kenarı, diğerinin karşı kenarıdır. Bu yüzden cos x = sin(90° − x) olur.'),
  ('İç teğet çemberinin yarıçapı 3 cm ve çevresi 36 cm olan bir üçgenin alanı kaç cm²\'dir?', '54 cm²', ['108 cm²', '36 cm²', '27 cm²'], 'Üçgenin alanı iç teğet yarıçapı ile yarı çevrenin çarpımıdır: 3 · 18 = 54 cm².'),
  ('Yüksekliği 9 cm olan eşkenar bir üçgenin içine, üç kenara birden değecek biçimde çizilen çemberin yarıçapı kaç cm\'dir?', '3 cm', ['4,5 cm', '6 cm', '3√3 cm'], 'Eşkenar üçgende iç teğet merkezi ağırlık merkezidir ve tabana uzaklığı yüksekliğin üçte biridir: 9/3 = 3 cm.'),
  ('Kenarları 5, 5 ve 6 cm olan ikizkenar üçgenin alanı Heron formülüyle hesaplanırsa kaç cm² bulunur?', '12 cm²', ['15 cm²', '24 cm²', '10,5 cm²'], 'u = 8 olur. Alan √(8 · 3 · 3 · 2) = √144 = 12 cm²\'dir. Tabana ait yükseklik 4 alınarak da 6 · 4 / 2 = 12 doğrulanır.'),
  ('İki kenarı 4√2 cm ve 6 cm, aralarındaki açı 45° olan üçgenin alanı kaç cm²\'dir?', '12 cm²', ['24 cm²', '12√2 cm²', '6√2 cm²'], 'Alan (1/2) · 4√2 · 6 · (√2/2) = (1/2) · 6 · 4 = 12 cm² olur.'),
  ('Bir ABC üçgeninin alanı S\'dir. AB ve AC kenarları iki katına çıkarılıp A açısı aynı tutulursa yeni üçgenin alanı ne olur?', '4S', ['2S', '8S', 'S√2'], 'Alan (1/2) · AB · AC · sin A ile bulunur. İki kenar da iki katına çıkınca alan 2 · 2 = 4 katına çıkar.'),
  ('Benzer iki üçgenin alanları 25 cm² ve 64 cm²\'dir. Küçük üçgenin çevresi 15 cm ise büyük üçgenin çevresi kaç cm\'dir?', '24 cm', ['38,4 cm', '30 cm', '20 cm'], 'Alan oranı 25/64 ise benzerlik oranı 5/8\'dir. Büyük çevre 15 · 8/5 = 24 cm olur.'),
  ('Üç paralel doğru iki keseni kesiyor. Birinci kesende paraleller arasında 4 cm ve 6 cm\'lik parçalar oluşuyor. İkinci kesende ilk parça 6 cm ise ikinci parça kaç cm\'dir?', '9 cm', ['8 cm', '4 cm', '7,5 cm'], 'Paralel doğrular kesenleri orantılı parçalara ayırır: 4/6 = 6/x ve x = 9 cm bulunur.'),
  ('Göz yüksekliği 1,6 m olan bir kişi yere koyduğu aynaya 2 m uzaktan bakınca, aynadan 30 m uzaktaki bir binanın tepesini görüyor. Binanın yüksekliği kaç metredir?', '24 m', ['18,75 m', '30 m', '48 m'], 'Gelme ve yansıma açıları eşit olduğundan iki dik üçgen benzerdir: 1,6/2 = h/30 ve h = 24 m.'),
  ('ABCD paralelkenarında AC köşegeni çiziliyor. ABC ve CDA üçgenlerinin eşliği hangi kurala dayanarak en doğrudan gösterilir?', 'KKK (kenar-kenar-kenar)', ['AAA (açı-açı-açı)', 'KKA (kenar-kenar-açı)', 'Yalnız alanlarının eşitliği'], 'Paralelkenarda AB = CD ve BC = DA\'dır. AC ortak kenar olduğundan üç kenar karşılıklı eşittir.'),
  ('İkizkenar bir üçgende tabana ait kenarortay için hangisi doğrudur?', 'Aynı zamanda yükseklik ve tepe açısının açıortayıdır.', ['Tabanın uzunluğuna eşittir.', 'Yalnız yüksekliktir, açıortay değildir.', 'Bir yan kenarın yarısına eşittir.'], 'Kenarortay üçgeni KKK kuralıyla iki eş üçgene ayırır. Tabanda oluşan açılar eş ve bütünler olduğundan 90°\'dir, tepe açısı da ikiye bölünür.'),
  ('Kenarları 10 cm, 10 cm ve 12 cm olan ikizkenar bir üçgenin ağırlık merkezinin 12 cm\'lik tabana uzaklığı kaç cm\'dir?', '8/3 cm', ['4 cm', '16/3 cm', '2 cm'], 'Tabana ait yükseklik √(100 − 36) = 8 cm ve aynı zamanda kenarortaydır. Ağırlık merkezi tabandan bu uzunluğun üçte biri kadar uzaktadır: 8/3 cm.'),
  ('Benzerlik oranı 4/7 olan iki üçgende karşılıklı kenarortayların uzunlukları oranı kaçtır?', '4/7', ['16/49', '64/343', '2/√7'], 'Benzer üçgenlerde karşılıklı bütün uzunluklar (kenar, yükseklik, kenarortay, açıortay) benzerlik oranıyla orantılıdır.'),
  ('ABC üçgeninin kenarortayları AD, BE ve CF\'dir. AD = 9, BE = 12 ve CF = 15 ise G ağırlık merkezi için AG + BG + CG toplamı kaçtır?', '24', ['36', '18', '12'], 'Her kenarortayın köşeye yakın parçası kenarortayın 2/3\'üdür: (2/3)(9 + 12 + 15) = 24.'),
  ('Bir haritada benzer iki üçgen bölge çizilmiştir. Bölgelerin karşılıklı kenarları 3 cm ve 4,5 cm ise küçük bölgenin alanı büyük bölgenin alanının kaçta kaçıdır?', '4/9', ['2/3', '8/27', '1/2'], 'Benzerlik oranı 3/4,5 = 2/3\'tür. Alanlar oranı (2/3)² = 4/9 olur.'),
  ('Bir dış açısı, bir iç açısının dörtte birine eşit olan düzgün çokgen kaç kenarlıdır?', '10', ['8', '9', '12'], 'İç açı 4x, dış açı x ise 5x = 180 ve x = 36° olur. Kenar sayısı 360 / 36 = 10\'dur.'),
  ('İç bükey (konkav) bir çokgeni dışbükey çokgenden ayıran özellik hangisidir?', 'En az bir iç açısının 180°\'den büyük olması', ['Kenar sayısının çift olması', 'Bütün kenarlarının eşit olması', 'Köşegen sayısının kenar sayısından az olması'], 'İç bükey çokgende en az bir iç açı 180°\'yi aşar ve bazı köşegenler çokgenin dışından geçer.'),
  ('On beş kenarlı dışbükey bir çokgenin dış açılarının ölçüleri toplamı kaç derecedir?', '360°', ['2340°', '180°', '2700°'], 'Kenar sayısı ne olursa olsun dışbükey bir çokgenin (her köşede bir tane alınan) dış açıları toplamı 360°\'dir.'),
  ('İç yarıçapı 10 m, dış yarıçapı 12 m olan dairesel bir koşu pistinin alanı kaç m²\'dir?', '44π m²', ['4π m²', '22π m²', '144π m²'], 'Pist bir halkadır: π(144 − 100) = 44π m².'),
  ('Alanı 36π cm² olan bir halkanın iç yarıçapı 8 cm ise dış yarıçapı kaç cm\'dir?', '10 cm', ['9 cm', '12 cm', '14 cm'], 'π(R² − 64) = 36π ise R² = 100 ve R = 10 cm bulunur.'),
  ('4 m × 3 m boyutlarındaki dikdörtgen bir zemin, kenarı 20 cm olan kare fayanslarla boşluksuz kaplanacaktır. Kaç fayans gerekir?', '300', ['60', '150', '1200'], 'Zemin 400 cm × 300 cm\'dir. Bir sırada 20, diğer yönde 15 fayans olur: 20 · 15 = 300.'),
  ('Kenarları 25 m ve 15 m olan dikdörtgen bir bahçenin çevresine köşelerden başlayarak 2,5 m arayla direk dikilecektir. Kaç direk gerekir?', '32', ['30', '33', '40'], 'Çevre 80 m\'dir. Kapalı bir çizgide direk sayısı aralık sayısına eşittir: 80 / 2,5 = 32.'),
  ('Köşeleri A(0, 0), B(4, 0), C(6, 3) ve D(2, 3) olan ABCD paralelkenarının alanı kaç birimkaredir?', '12', ['15', '18', '7,5'], 'AB tabanı 4 birim, CD kenarı da y = 3 doğrusu üzerindedir. Yükseklik 3 olduğundan alan 4 · 3 = 12 birimkare olur.'),
  ('Birinci bölgede bulunan ve her iki koordinat eksenine de teğet olan, yarıçapı 3 birim olan çemberin denklemi hangisidir?', '(x − 3)² + (y − 3)² = 9', ['x² + y² = 9', '(x + 3)² + (y + 3)² = 9', '(x − 3)² + (y − 3)² = 3'], 'Her iki eksene teğet olduğundan merkez eksenlerden 3\'er birim uzaktadır: (3, 3). Yarıçapın karesi 9\'dur.'),
  ('x² + y² = 25 çemberinin y = 3 doğrusu tarafından kesilen kirişinin uzunluğu kaç birimdir?', '8', ['4', '6', '10'], 'y = 3 için x² = 16 ve x = ±4 olur. Kesişim noktaları (−4, 3) ve (4, 3)\'tür; aralarındaki uzaklık 8\'dir.'),
  ('Bir öğrenci x² + y² + 4 = 0 denkleminin bir çember belirttiğini söylüyor. Bu iddia için doğru değerlendirme hangisidir?', 'Yanlıştır, denklemi sağlayan gerçek nokta yoktur.', ['Doğrudur, merkezi orijin ve yarıçapı 2\'dir.', 'Doğrudur, yarıçapı 4\'tür.', 'Yanlıştır, bu bir doğru denklemidir.'], 'x² + y² her zaman sıfır veya pozitiftir. x² + y² = −4 olamayacağından düzlemde bu denklemi sağlayan nokta yoktur.'),
  ('18 ayrıtı olan bir prizmanın kaç köşesi vardır?', '12', ['9', '10', '18'], '3n = 18 ise taban altıgendir. Prizmanın köşe sayısı 2n = 12 olur.'),
  ('Altı eş kare tek bir sıra hâlinde yan yana dizilerek elde edilen şekil hakkında hangisi doğrudur?', 'Katlanınca küp oluşturmaz.', ['Küpün 11 açınımından biridir.', 'Katlanınca kare piramit oluşur.', 'Katlanınca dikdörtgenler prizması oluşur.'], 'Dört kare yan yana katlanınca küpün yan yüzlerini kapatır. Kalan iki kare de aynı yöne düşüp üst üste gelir; alt ve üst yüzler oluşmaz.'),
  ('Bir dik koni, tepe noktasından geçen ve tabana dik olan bir düzlemle kesilirse kesit hangi şekildir?', 'İkizkenar üçgen', ['Daire', 'Elips', 'Dikdörtgen'], 'Düzlem tepe noktası ve taban merkezinden geçer. Kesit, iki kenarı ana doğru, tabanı çap olan ikizkenar üçgendir.'),
  ('Bütün ayrıtlarının uzunlukları toplamı 48 cm olan bir küpün toplam yüzey alanı kaç cm²\'dir?', '96 cm²', ['64 cm²', '144 cm²', '24 cm²'], 'Küpün 12 ayrıtı olduğundan bir ayrıt 4 cm\'dir. Yüzey alanı 6 · 16 = 96 cm² olur.'),
  ('Bir dik silindir, eksenine paralel bir düzlemle kesilirse kesit hangi şekildedir?', 'Dikdörtgen', ['Daire', 'Elips', 'Yamuk'], 'Eksene paralel düzlem iki tabanı birer kiriş boyunca, yanal yüzeyi iki ana doğru boyunca keser. Bu dört doğru parçası bir dikdörtgen oluşturur.'),
  ('10 m uzunluğundaki bir merdivenin alt ucu duvardan 6 m uzaktadır. Alt uç duvardan 2 m daha uzaklaştırılırsa merdivenin üst ucu kaç metre aşağı kayar?', '2 m', ['1 m', '3 m', '1,5 m'], 'Başta üst uç √(100 − 36) = 8 m yüksekliktedir. Alt uç 8 m uzaklaşınca yükseklik √(100 − 64) = 6 m olur. Kayma 2 m\'dir.'),
  ('Kenarları eşit üçgen biçimli bir trafik levhasının tabanı ile tepesi arasındaki dik uzaklık 60 cm\'dir. Levhanın yüzey alanı kaç cm²\'dir?', '1200√3 cm²', ['1800 cm²', '3600√3 cm²', '600√3 cm²'], 'Yükseklik a√3/2 = 60 ise a = 40√3 cm\'dir. Alan (1/2) · 40√3 · 60 = 1200√3 cm² olur.'),
  ('30-60-90 üçgeninde uzun dik kenar 9 cm ise hipotenüs kaç cm\'dir?', '6√3 cm', ['18 cm', '9√3 cm', '3√3 cm'], 'Kısa kenar 9/√3 = 3√3 cm\'dir. Hipotenüs kısa kenarın iki katı olduğundan 6√3 cm olur.'),
  ('Kare biçimli bir kâğıt köşegeni boyunca kesilerek iki eş parçaya ayrılıyor. Kesim çizgisi 10 cm ise parçalardan birinin alanı kaç cm²\'dir?', '25 cm²', ['50 cm²', '25√2 cm²', '20 cm²'], 'Her parça hipotenüsü 10 cm olan ikizkenar dik üçgendir. Dik kenarlar 5√2 cm, alan (5√2)²/2 = 25 cm² olur.'),
  ('Güneş ışınlarının yatayla 60° açı yaptığı bir anda 6 m yüksekliğindeki bir direğin gölgesi kaç metredir?', '2√3 m', ['3 m', '6√3 m', '3√3 m'], 'tan 60° = 6 / gölge olduğundan gölge 6/√3 = 2√3 m olur.'),
  ('m > n > 0 tam sayıları için (m² − n², 2mn, m² + n²) üçlüsü bir Pisagor üçlüsü verir. m = 3 ve n = 2 için elde edilen üçlü hangisidir?', '5, 12, 13', ['3, 4, 5', '6, 8, 10', '8, 15, 17'], 'm² − n² = 5, 2mn = 12, m² + n² = 13 olur. 25 + 144 = 169 eşitliği doğrulanır.'),
  ('Dik üçgende bir dar açı büyüdükçe o açının sinüsü nasıl değişir?', 'Artar.', ['Azalır.', 'Değişmez.', 'Önce azalır sonra artar.'], 'Hipotenüs sabit tutulursa açı büyüdükçe karşı dik kenar uzar. Bu nedenle 0° ile 90° arasında sinüs artar, kosinüs azalır.'),
  ('Yarıçapı 7 cm olan yarım dairesel bir bölgenin çevresi kaç cm\'dir?', '7π + 14 cm', ['7π cm', '14π cm', '14π + 14 cm'], 'Çevre yarım çember yayı (7π) ile çaptan (14 cm) oluşur: 7π + 14 cm.'),
  ('Bir el yelpazesi açıldığında, 6 cm uzunluğundaki iki kenar çubuğu arasında 120°\'lik bir daire dilimi oluşuyor. Yelpazenin dış sınırının toplam uzunluğu kaç cm\'dir?', '12 + 4π cm', ['4π cm', '6 + 4π cm', '12 + 12π cm'], 'Yay uzunluğu 2π · 6 · 120/360 = 4π cm\'dir. Çevre iki yarıçap ile yayın toplamıdır: 12 + 4π cm.'),
  ('Uzunluğu 5 cm olan akrebin ucu 3 saatte kaç cm\'lik yay çizer?', '2,5π cm', ['5π cm', '10π cm', '1,25π cm'], 'Akrep 12 saatte tam tur atar. 3 saat turun dörtte biridir: 2π · 5 / 4 = 2,5π cm.'),
  ('Yarıçapları 7 cm ve 3 cm olan iki çember birbirine içten teğettir. Merkezleri arasındaki uzaklık kaç cm\'dir?', '4 cm', ['10 cm', '3,5 cm', '7 cm'], 'İçten teğet çemberlerde merkezler arası uzaklık yarıçapların farkına eşittir: 7 − 3 = 4 cm.'),
  ('Aynı merkezli iki çemberde aynı merkez açının gördüğü yaylardan biri 6 cm, diğeri 9 cm\'dir. Küçük çemberin yarıçapı 4 cm ise büyük çemberin yarıçapı kaç cm\'dir?', '6 cm', ['9 cm', '5 cm', '7,5 cm'], 'Aynı merkez açı için yay uzunluğu yarıçapla orantılıdır: 6/4 = 9/R ve R = 6 cm.'),
  ('Bir çemberde AB ve CD kirişleri birbirine dik olarak E noktasında kesişiyor. AE = 2, EB = 6 ve CE = 3 ise ED uzunluğu kaçtır?', '4', ['3', '9', '5'], 'Kesişen kirişler için AE · EB = CE · ED olur: 12 = 3 · ED ve ED = 4. Kirişlerin dik olması bu bağıntıyı değiştirmez.'),
  ('Orta tabanı 12 cm, yüksekliği 5 cm olan bir yamuğun alanı kaç cm²\'dir?', '60 cm²', ['30 cm²', '17 cm²', '120 cm²'], 'Yamuğun alanı orta taban ile yüksekliğin çarpımıdır, çünkü orta taban (a + c)/2\'ye eşittir: 12 · 5 = 60 cm².'),
  ('Tabanları 6 cm ve 14 cm olan ikizkenar yamuğun taban açıları 45° ise alanı kaç cm²\'dir?', '40 cm²', ['80 cm²', '40√2 cm²', '20 cm²'], 'Yan kenarların tabana izdüşümü (14 − 6)/2 = 4 cm\'dir. 45°\'de yükseklik de 4 cm olur. Alan (6 + 14)/2 · 4 = 40 cm².'),
  ('Bir haritada 6 km\'lik gerçek uzaklık 3 cm olarak gösterilmiştir. Haritanın ölçeği hangisidir?', '1 : 200 000', ['1 : 20 000', '1 : 2 000 000', '1 : 2000'], '6 km = 600 000 cm\'dir. Ölçek 3 : 600 000 = 1 : 200 000 olur.'),
  ('Çapı gören çevre açının dik açı olduğunu söyleyen teorem, adını hangi antik düşünürden alır?', 'Thales', ['Öklid', 'Arşimet', 'Apollonius'], 'Bu teorem Miletli Thales\'e atfedilir ve Thales teoremi olarak bilinir. Thales\'in adı ayrıca temel orantı teoremiyle de anılır.'),
];
